import java.io.*;
import java.util.*;

// Stand-in for the given Main.class (javap -c): the TC first, then the string; results printed with printf + \r\n
class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        System.out.println("1. Test f1()");
        System.out.println("2. Test f2()");
        System.out.print("Enter TC (1 or 2): ");
        int tc = sc.nextInt();
        sc.nextLine();
        System.out.println("Enter a string:");
        String s = sc.nextLine();
        IString t = new MyString();
        System.out.println("OUTPUT:");
        switch (tc) {
            case 1: System.out.printf("%d\r\n", t.f1(s)); break;
            case 2: System.out.printf("%s\r\n", t.f2(s)); break;
        }
        System.out.println();
    }
}
